  metaTitle: "Will My Sofa Fit Through the Door?",
  metaDescription: "Check diagonal depth, not width, before you order. Learn the on-its-side rule, when to remove hinges, and when a knock-down frame is the way out.",
  heroImage: "/images/articles/door-orange-sofa-hero.webp",
